// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract via its receive() from a random funder, owner is a random actor
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);

        // owner withdraws the full balance
        vm.prank(c.Owner());
        bool ok = true;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input, after a successful owner withdraw,
        // the contract retains zero Ether.
        assertTrue(ok && address(c).balance == 0);
    }
}

