pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, bytes calldata data, uint256 v) public {
        // Only the Owner (this test contract, deployer) may call Command.
        // Target must not be the contract itself (self-call with data would revert
        // at the callee in the reference too, changing the balance legitimately).
        vm.assume(adr != address(c));
        v = bound(v, 1, 100 ether);

        address owner = address(this);
        vm.deal(owner, v);

        uint256 before = address(c).balance;
        vm.prank(owner);
        c.Command{value: v}(adr, data);

        // General rule: an Owner's Command never keeps value in the contract;
        // msg.value is always forwarded out via the low-level call.
        assertTrue(address(c).balance == before);
    }
}

