pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint256 amount, uint256 extra) public {
        vm.assume(amount > 0);
        extra = bound(extra, 1, 100 ether);
        amount = bound(amount, 1, 10 ether);
        // ensure amount < extra so sending only msg.value differs from sending the whole balance
        vm.assume(amount < extra);

        address actor = address(uint160(0xA1000 + (seed % 1000)));
        address adr = address(uint160(0xB2000 + (seed % 1000)));

        // c holds `extra` ether, more than the sent value
        vm.deal(address(c), extra);
        vm.deal(actor, amount);

        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, adr, hex"")
        );
        assertTrue(ok && address(c).balance == balBefore - amount);
    }
}

