pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = c.Owner(); }

    function testFuzz_property(uint256 seed, uint256 amount, bytes calldata data) public {
        vm.assume(seed > 0);
        amount = bound(amount, 0, 1e30);

        // give c some pre-existing Ether (the buffer the mutant would steal)
        vm.deal(address(c), seed);
        uint256 pre = address(c).balance;

        // fund the owner and drive c through Command to a willing sink
        Sink sink = new Sink();
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, address(sink), data)
        );
        assertTrue(ok);

        // General rule: Command forwards exactly msg.value, so c keeps its prior balance.
        assertTrue(address(c).balance == pre);
    }
}

contract Sink {
    fallback() external payable {}
    receive() external payable {}
}

