pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 extra, uint256 amount, address actor, bytes memory data) public {
        // 1. keep the domain wide but admissible
        extra = bound(extra, 1, 1e18);
        amount = bound(amount, 1, 1e18);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(data.length == 0); // empty calldata so the callee merely receives Ether

        // 2. set up the scenario: c holds extra Ether beyond the incoming msg.value
        vm.deal(address(c), extra);
        vm.deal(actor, amount);
        uint256 preBalance = address(c).balance;

        // 3. drive c through Command and assert the general rule
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", actor, data));
        assertTrue(ok && address(c).balance == preBalance - amount);
    }
}

