pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 valueSent, uint256 extra, address adr) public {
        // admissible domain: positive amounts, wide but sane
        valueSent = bound(valueSent, 1, 1e21);
        extra = bound(extra, 1, 1e21);
        // recipient must be a plain account: no code, not c, not the test, not a precompile
        vm.assume(adr.code.length == 0);
        vm.assume(adr != address(c));
        vm.assume(adr != address(this));
        vm.assume(uint160(adr) > 10);

        // the test contract is the Owner of c (deployed in setUp)
        vm.deal(address(this), valueSent + extra);

        // pre-fund c with `extra` ether through its public receive()
        (bool funded,) = address(c).call{value: extra}("");
        assertTrue(funded, "funding c must succeed");

        uint256 preBalance = address(c).balance; // == extra + 0

        // Owner drives c through Command with the fuzzed value
        (bool ok,) = address(c).call{value: valueSent}(
            abi.encodeWithSelector(c.Command.selector, adr, hex"")
        );
        assertTrue(ok, "Command by Owner must succeed");

        // RULE: a correct Command forwards exactly msg.value, so c's own
        // pre-existing balance `extra` is untouched.
        // The mutant forwards address(this).balance (extra + valueSent),
        // draining c to 0, which violates this whenever extra > 0.
        assertTrue(address(c).balance == preBalance - valueSent);
    }
}

