import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 extra, uint256 amount, address adr) public {
        vm.assume(adr != address(c) && adr.code.length == 0);
        amount = bound(amount, 1 wei, 1 ether);
        extra = bound(extra, amount + 1 wei, 2 ether); // contract holds more than msg.value
        vm.deal(address(this), amount);
        vm.deal(address(c), extra); // pre-fund c with extra Ether
        uint256 pre = address(c).balance;
        vm.prank(address(this)); // test contract is Owner (deployer)
        bool ok;
        try c.Command{value: amount}(adr, "") { ok = true; } catch { ok = false; }
        // Correct: successful Command forwards exactly msg.value, leaving pre - amount in c.
        assertTrue(ok && address(c).balance == pre - amount);
    }
}

